import { type App, Modal } from 'obsidian';
import { describeWarning, type EmbedWarning } from './embeds';
import type { Preview, StoryView, Verdict } from './preview';

/**
 * Preview window. SECURITY: every string coming from Refinr (generated by a language model) is inserted as plain text
 * with `createEl({ text })` / `setText` — never as HTML or rendered Markdown (checked by `tests/plain-text.test.ts`).
 */
export type PreviewState =
	| { kind: 'reading' }
	| { kind: 'analyzing'; chars: number; limit: number; warnings: EmbedWarning[] }
	| { kind: 'error'; message: string; warnings: EmbedWarning[] }
	| { kind: 'done'; preview: Preview; chars: number; warnings: EmbedWarning[] };

const VERDICT_LABELS: Record<Verdict, string> = {
	'ai-ready': 'ai-ready',
	'validation-necessaire': 'validation-necessaire',
	unknown: 'no verdict',
};

export class PreviewModal extends Modal {
	private state: PreviewState = { kind: 'reading' };
	private shown = false;

	constructor(
		app: App,
		private readonly noteName: string,
	) {
		super(app);
	}

	get isShown(): boolean {
		return this.shown;
	}

	get current(): PreviewState {
		return this.state;
	}

	setState(state: PreviewState): void {
		this.state = state;
		if (this.shown) {
			this.render();
		}
	}

	onOpen(): void {
		this.shown = true;
		this.render();
	}

	onClose(): void {
		this.shown = false;
		this.contentEl.empty();
	}

	private render(): void {
		const el = this.contentEl;
		el.empty();
		el.addClass('refinr-preview');
		this.setTitle(`Refinr preview: ${this.noteName}`);
		const state = this.state;
		switch (state.kind) {
			case 'reading':
				el.createEl('p', { text: 'Reading the note and its embeds…' });
				return;
			case 'analyzing':
				renderWarnings(el, state.warnings);
				el.createEl('p', {
					text: `Refinr is analyzing ${state.chars.toLocaleString('en-US')} characters (limit ${state.limit.toLocaleString('en-US')}).`,
				});
				el.createEl('p', {
					cls: 'refinr-muted',
					text: 'This can take several minutes. You can close this window: a notice will tell you when the preview is ready.',
				});
				return;
			case 'error':
				renderWarnings(el, state.warnings);
				el.createEl('p', { cls: 'refinr-error', text: state.message });
				return;
			case 'done':
				renderWarnings(el, state.warnings);
				renderPreview(el, state.preview, state.chars);
				return;
		}
	}
}

/** Warnings change what was sent: shown first, in a visible box, with the characters left out when known. */
function renderWarnings(el: HTMLElement, warnings: EmbedWarning[]): void {
	if (warnings.length === 0) {
		return;
	}
	const box = el.createDiv({ cls: 'refinr-warnings' });
	const dropped = warnings.reduce((sum, warning) => sum + (warning.droppedChars ?? 0), 0);
	box.createEl('p', {
		cls: 'refinr-warnings-title',
		text:
			`The text sent differs from the note: ${warnings.length} embed problem(s)` +
			(dropped > 0 ? `, ${dropped.toLocaleString('en-US')} characters left out.` : '.'),
	});
	const items = box.createEl('ul');
	for (const warning of warnings) {
		items.createEl('li', { text: describeWarning(warning) });
	}
}

function renderPreview(el: HTMLElement, preview: Preview, chars: number): void {
	const t = preview.totals;
	el.createEl('p', {
		cls: 'refinr-totals',
		text:
			`${t.epics} epic(s) · ${t.stories} story(ies) · ${t.tasks} sub-task(s) · ` +
			`${t.aiReady} ai-ready · ${t.needsValidation} validation-necessaire` +
			(t.noVerdict > 0 ? ` · ${t.noVerdict} without verdict` : '') +
			` — from ${chars.toLocaleString('en-US')} characters.`,
	});
	if (preview.epics.length === 0) {
		el.createEl('p', { text: 'Refinr found nothing to turn into a backlog in this note.' });
		return;
	}
	for (const epic of preview.epics) {
		const epicEl = el.createDiv({ cls: 'refinr-epic' });
		epicEl.createEl('h3', { text: epic.name === '' ? 'Untitled epic' : epic.name });
		addMeta(epicEl, epic.priority, epic.labels);
		addText(epicEl, epic.description, 'refinr-description');
		for (const story of epic.stories) {
			renderStory(epicEl, story);
		}
	}
}

function renderStory(parent: HTMLElement, story: StoryView): void {
	const details = parent.createEl('details', { cls: 'refinr-story' });
	const summary = details.createEl('summary');
	summary.createSpan({ cls: 'refinr-story-title', text: story.title === '' ? 'Untitled story' : story.title });
	summary.createSpan({ cls: `refinr-verdict refinr-verdict-${story.verdict}`, text: VERDICT_LABELS[story.verdict] });
	if (story.storyPoints !== null) {
		summary.createSpan({ cls: 'refinr-points', text: `${story.storyPoints} pts` });
	}

	if (story.asA !== '' || story.iWant !== '' || story.soThat !== '') {
		addText(details, `As ${story.asA}, I want ${story.iWant}, so that ${story.soThat}.`, 'refinr-user-story');
	}
	addMeta(details, story.priority, story.labels);
	addText(details, story.description, 'refinr-description');
	if (story.verdictReason !== '') {
		addText(details, `Verdict: ${story.verdictReason}`, 'refinr-verdict-reason');
	}
	if (story.acceptanceCriteria.length > 0) {
		details.createEl('p', { cls: 'refinr-subheading', text: 'Acceptance criteria' });
		const list = details.createEl('ul');
		for (const criterion of story.acceptanceCriteria) {
			list.createEl('li', { text: criterion });
		}
	}
	if (story.tasks.length > 0) {
		details.createEl('p', { cls: 'refinr-subheading', text: 'Sub-tasks' });
		const list = details.createEl('ul');
		for (const task of story.tasks) {
			const item = list.createEl('li');
			item.createSpan({ text: task.title === '' ? 'Untitled sub-task' : task.title });
			if (task.estimatedHours !== null) {
				item.createSpan({ cls: 'refinr-muted', text: ` (${task.estimatedHours} h)` });
			}
			addText(item, task.description, 'refinr-description');
		}
	}
}

function addMeta(parent: HTMLElement, priority: string, labels: string[]): void {
	const parts = [priority === '' ? '' : `Priority: ${priority}`, labels.length === 0 ? '' : `Labels: ${labels.join(', ')}`];
	addText(parent, parts.filter((part) => part !== '').join(' · '), 'refinr-muted');
}

function addText(parent: HTMLElement, text: string, cls: string): void {
	if (text !== '') {
		parent.createEl('p', { cls, text });
	}
}
